    const res = new Set();
    const maxBits = 60; // enough for numbers up to 1e18

    for (let len = 2; len <= maxBits; len++) {
        for (let zeroPos = 0; zeroPos < len; zeroPos++) {
            for (let onePos = 0; onePos < len; onePos++) {
                if (onePos === zeroPos) continue;
                if (onePos === len - 1) continue; // leading bit can't be zero

                let num = 0n;
                for (let i = 0; i < len; i++) {
