function generateNumbers(limit) {
    const res = [];
    // We need numbers with exactly one zero in binary, no leading zeros.
    // Let total bits = n (n >= 2), choose position of zero (0-based from LSB) as z (0 <= z < n).
    // All other bits are 1.
    // So number = (1 << n) - 1 - (1 << z), but we must ensure highest bit is 1 (no leading zeros).
    // That formula already ensures highest bit is 1.
    for (let n = 2; ; n++) {
        // minimal number for this n is when zero at position 0: (1<<n)-1-1 = (1<<n)-2
        // if that exceeds limit, further n will only be larger
        const minVal = (1n << BigInt(n)) - 2n;
        if (minVal > limit) break;

        for (let z = 0; z < n; z++) {
            const val = (1n << BigInt(n)) - 1n - (1n << BigInt(z));
            if (val > limit) continue;
            res.push(val);
        }
    }
    res.sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
    return res;
}

function countInRange(arr, a, b) {
    // binary search lower bound for a
    let l = 0, r = arr.length;
    while (l < r) {
        const m = (l + r) >> 1;
        if (arr[m] < a) l = m + 1;
        else r = m;
    }
    const start = l;
    // binary search upper bound for b
    l = 0; r = arr.length;
    while (l < r) {
        const m = (l + r) >> 1;
        if (arr[m] <= b) l = m + 1;
        else r = m;
    }
    const end = l;
    return end - start;
}

