function countUpTo(n) {
    if (n <= 0n) return 0n;

    const s = n.toString(2);
    const len = s.length;

    // dp[pos][ones][zeroUsed][started]
    const dp = {};
    function key(pos, ones, zeroUsed, started, tight) {
        return `${pos}|${ones}|${zeroUsed ? 1 : 0}|${started ? 1 : 0}|${tight ? 1 : 0}`;
    }

    function dfs(pos, ones, zeroUsed, started, tight) {
        if (pos === len) {
            return (started && zeroUsed && ones >= 1) ? 1n : 0n;
        }
        const k = key(pos, ones, zeroUsed, started, tight);
        if (!tight && dp[k] !== undefined) return dp[k];

        const limit = tight ? (s[pos] === '1' ? 1 : 0) : 1;
        let res = 0n;

        for (let bit = 0; bit <= limit; bit++) {
            const ntight = tight && (bit === limit);
            if (!started) {
                if (bit === 0) {
                    // still not started
                    res += dfs(pos + 1, ones, zeroUsed, false, ntight);
                } else {
                    // first 1
                    res += dfs(pos + 1, ones + 1, zeroUsed, true, ntight);
                }
            } else {
                if (bit === 1) {
                    res += dfs(pos + 1, ones + 1, zeroUsed, true, ntight);
                } else {
                    if (!zeroUsed) {
                        res += dfs(pos + 1, ones, true, true, ntight);
                    }
                }
            }
        }

        if (!tight) dp[k] = res;
        return res;
    }

    return dfs(0, 0, false, false, true);
}

