function countUpTo(n) {
    if (n <= 0n) return 0n;

    const s = n.toString(2);
    const len = s.length;

    // dp[pos][ones][zeroUsed][started]
    // pos: 0..len
    // ones: 0..len
    // zeroUsed: 0 or 1
    // started: 0 or 1
    const dp = [];
    for (let pos = 0; pos <= len; pos++) {
        dp[pos] = [];
        for (let ones = 0; ones <= len; ones++) {
            dp[pos][ones] = [];
            for (let z = 0; z < 2; z++) {
                dp[pos][ones][z] = [0n, 0n]; // started = 0 or 1
            }
        }
    }

    dp[0][0][0][0] = 1n;

    for (let pos = 0; pos < len; pos++) {
        const bit = s[pos] === '1' ? 1 : 0;
        for (let ones = 0; ones <= len; ones++) {
            for (let z = 0; z < 2; z++) {
                for (let started = 0; started < 2; started++) {
                    let cur = dp[pos][ones][z][started];
                    if (cur === 0n) continue;

                    // place 0
                    if (bit === 1) {
                        // can place 0
                        let nStarted = started;
                        let nOnes = ones;
                        let nZ = z;
                        if (started === 1) {
                            if (z === 1) {
                                // would create second zero, skip
                            } else {
                                nZ = 1;
                                dp[pos + 1][nOnes][nZ][nStarted] += cur;
                            }
                        } else {
                            // still leading zeros
                            dp[pos + 1][nOnes][nZ][nStarted] += cur;
                        }
                    }

                    // place 1
                    if (bit === 1) {
                        let nStarted = 1;
                        let nOnes = ones + 1;
                        let nZ = z;
                        if (nOnes <= len) {
                            dp[pos + 1][nOnes][nZ][nStarted] += cur;
                        }
                    }
                }
            }
        }
    }

    let ans = 0n;
    for (let ones = 0; ones <= len; ones++) {
        ans += dp[len][ones][1][1]; // exactly one zero, started
    }
    return ans;
}

